citations.excerpt:
    {% if page == pages.current %}
        <li class="ec-pager__item--active"><a href="{{ path(
            app.request.attributes.get('_route'),
            app.request.query.all|merge({'pageno': page})) }}"> {{ page }} </a></li>
    {% else %}
        <li class="ec-pager__item"><a href="{{ path(
            app.request.attributes.get('_route'),
            app.request.query.all|merge({'pageno': page})) }}"> {{ page }} </a></li>
    {% endif %}
{% endfor %}
